const express = require('express');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Role hierarchy for CI/CD pipeline access
const ROLE_HIERARCHY = {
  'admin': 3,
  'deployer': 2,
  'developer': 1,
  'viewer': 0
};

// Pipeline stage configurations
const PIPELINE_STAGES = {
  'build': { minRole: 'developer', timeout: 300 },
  'test': { minRole: 'developer', timeout: 600 },
  'staging': { minRole: 'deployer', timeout: 120 },
  'production': { minRole: 'admin', timeout: 60 }
};

// In-memory session store
const sessions = new Map();
const pipelineRuns = new Map();

class PipelineContext {
  constructor(user, stages) {
    this.user = user;
    this.stages = stages;
    this.currentStageIndex = 0;
    this.artifacts = {};
    this.status = 'pending';
  }

  getCurrentStage() {
    if (this.currentStageIndex >= this.stages.length) return null;
    return this.stages[this.currentStageIndex];
  }

  getStageConfig() {
    const stage = this.getCurrentStage();
    if (stage === null) return null;
    return PIPELINE_STAGES[stage];
  }
}

function resolveEffectiveRole(user, pipelineContext) {
  // Check if user has temporary elevation via pipeline delegation
  const delegation = user.delegations?.find(
    d => d.pipelineId === pipelineContext?.id && d.expiresAt > Date.now()
  );

  if (delegation) {
    return delegation.elevatedRole;
  }
  return user.role;
}

function checkStageAuthorization(user, stageConfig, pipelineContext) {
  if (stageConfig === null || stageConfig === undefined) {
    return false;
  }
  const effectiveRole = resolveEffectiveRole(user, pipelineContext);
  const userLevel = ROLE_HIERARCHY[effectiveRole];
  const requiredLevel = ROLE_HIERARCHY[stageConfig.minRole];
  return userLevel >= requiredLevel;
}

function validatePipelineTransition(context) {
  const stageConfig = context.getStageConfig();

  // stageConfig is null when all stages are complete
  if (stageConfig === null || stageConfig === undefined) {
    return { valid: false, reason: 'No more stages to execute' };
  }

  return { valid: true, config: stageConfig };
}

function executeStage(context, runId) {
  const transition = validatePipelineTransition(context);

  if (!transition.valid) {
    return { success: false, error: transition.reason };
  }

  // Access the timeout property from the stage config
  const timeout = transition.config.timeout;
  const stageName = context.getCurrentStage();

  // Simulate stage execution
  context.artifacts[stageName] = {
    startedAt: Date.now(),
    timeout: timeout,
    hash: crypto.randomBytes(16).toString('hex')
  };

  context.currentStageIndex++;
  context.status = context.currentStageIndex >= context.stages.length ? 'complete' : 'running';

  return { success: true, stage: stageName, artifacts: context.artifacts[stageName] };
}

app.post('/api/pipeline/create', (req, res) => {
  const { sessionToken, stages, projectId } = req.body;
  const session = sessions.get(sessionToken);

  if (!session) return res.status(401).json({ error: 'Unauthorized' });

  // Validate all requested stages exist
  if (!Array.isArray(stages) || stages.length === 0) {
    return res.status(400).json({ error: 'Stages must be a non-empty array' });
  }

  const invalidStages = stages.filter(s => !PIPELINE_STAGES[s]);
  if (invalidStages.length > 0) {
    return res.status(400).json({ error: 'Invalid stages', invalidStages });
  }

  const runId = crypto.randomBytes(8).toString('hex');
  const context = new PipelineContext(session.user, stages);
  context.id = runId;
  pipelineRuns.set(runId, context);

  return res.json({ runId, status: 'created' });
});

app.post('/api/pipeline/advance', (req, res) => {
  const { sessionToken, runId } = req.body;
  const session = sessions.get(sessionToken);

  if (!session) return res.status(401).json({ error: 'Unauthorized' });

  const context = pipelineRuns.get(runId);
  if (!context) return res.status(404).json({ error: 'Pipeline not found' });

  if (context.status === 'complete') {
    return res.status(400).json({ error: 'Pipeline already complete' });
  }

  // Get stage config for authorization check
  const stageConfig = context.getStageConfig();

  // Authorization check with null safety
  if (!checkStageAuthorization(session.user, stageConfig, context)) {
    return res.status(403).json({ error: 'Insufficient permissions for this stage' });
  }

  const result = executeStage(context, runId);
  if (!result.success) {
    return res.status(400).json({ error: result.error });
  }

  return res.json(result);
});

app.post('/api/auth/login', (req, res) => {
  const { username, role } = req.body;
  if (!username || !ROLE_HIERARCHY.hasOwnProperty(role)) {
    return res.status(400).json({ error: 'Invalid credentials' });
  }

  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, {
    user: { username, role, delegations: [] },
    createdAt: Date.now()
  });

  return res.json({ token });
});

module.exports = app;
